-- ts-ai-consultant 1.0.0 – konverzace, spotřeba, rozpočet, limity, leady (SQLite)
CREATE TABLE IF NOT EXISTS ts_ai_conversations (id VARCHAR(64) NOT NULL PRIMARY KEY, lang VARCHAR(8) NOT NULL, ip_hash VARCHAR(64) NOT NULL, page VARCHAR(300) NOT NULL DEFAULT '', turns INTEGER NOT NULL DEFAULT 0, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL);
CREATE TABLE IF NOT EXISTS ts_ai_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, conv_id VARCHAR(64) NOT NULL REFERENCES ts_ai_conversations(id), role VARCHAR(10) NOT NULL, text TEXT NOT NULL, meta VARCHAR(200) NOT NULL DEFAULT '', created_at VARCHAR(19) NOT NULL);
CREATE INDEX IF NOT EXISTS ts_ai_messages_conv ON ts_ai_messages (conv_id, id);
CREATE TABLE IF NOT EXISTS ts_ai_usage (id INTEGER PRIMARY KEY AUTOINCREMENT, month VARCHAR(7) NOT NULL, conv_id VARCHAR(64), model VARCHAR(60) NOT NULL, in_tokens INTEGER NOT NULL DEFAULT 0, out_tokens INTEGER NOT NULL DEFAULT 0, cache_read INTEGER NOT NULL DEFAULT 0, cache_write INTEGER NOT NULL DEFAULT 0, cost_micro INTEGER NOT NULL DEFAULT 0, outcome VARCHAR(30) NOT NULL, created_at VARCHAR(19) NOT NULL);
CREATE INDEX IF NOT EXISTS ts_ai_usage_month ON ts_ai_usage (month);
CREATE TABLE IF NOT EXISTS ts_ai_reservations (id INTEGER PRIMARY KEY AUTOINCREMENT, month VARCHAR(7) NOT NULL, micro INTEGER NOT NULL, created_at VARCHAR(19) NOT NULL);
CREATE TABLE IF NOT EXISTS ts_ai_rate (bucket VARCHAR(120) NOT NULL PRIMARY KEY, window_start INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ts_ai_leads (id INTEGER PRIMARY KEY AUTOINCREMENT, submission_id VARCHAR(64) NOT NULL UNIQUE, conv_id VARCHAR(64), name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL, phone VARCHAR(40), company VARCHAR(160), website VARCHAR(300), message TEXT NOT NULL, transcript TEXT NOT NULL, lang VARCHAR(8) NOT NULL, consent_text VARCHAR(500) NOT NULL, consent_at VARCHAR(19) NOT NULL, sink_status VARCHAR(20) NOT NULL, sink_ref VARCHAR(60), created_at VARCHAR(19) NOT NULL);
